select t.as_super();
select t.signup('aa_admin','aa-admin@test.ge','{"role":"client","name":"AA Admin","company":"AA Admin","phone":"599772200","city":"tbilisi"}');
select t.signup('aa_b','aa-b@test.ge','{"role":"client","name":"AA Buyer","company":"AA Buyer","phone":"599772201","city":"tbilisi"}');
select t.signup('aa_s','aa-s@test.ge','{"role":"company","name":"AA Seller","company":"AA Seller","phone":"599772202","city":"tbilisi","industry":"other"}');
select t.signup('aa_other','aa-other@test.ge','{"role":"client","name":"AA Other","company":"AA Other","phone":"599772203","city":"tbilisi"}');
update public.profiles set role='admin' where id=t.uid('aa_admin');
update public.profiles set verified=true,verification_documents_status='approved',provide_categories=array['other'] where id=t.uid('aa_s');
select t.as_user('aa_b');
select t.put('aa_r',(public.create_request_full('AA test request','A sufficiently long request body','other','tbilisi',null,10,'pcs',current_date+7,'Warehouse','{}',gen_random_uuid())).id);
select t.put('aa_r2',(public.create_request_full('AA second request','A sufficiently long request body','other','tbilisi',null,10,'pcs',current_date+7,'Warehouse','{}',gen_random_uuid())).id);
select t.as_user('aa_s');
select t.put('aa_o',(public.send_offer(t.get('aa_r'),'A complete supplier offer',100,'total',true,5,true)).id);
select t.put('aa_o2',(public.send_offer(t.get('aa_r2'),'A complete supplier offer',100,'total',true,5,true)).id);
select t.as_user('aa_b');
select t.put('aa_d',(public.select_offer_deal(t.get('aa_o'))->>'id')::uuid);
select t.as_super();
insert into meetany_private.deal_issues(deal_id,actor_id,reason,body) values(t.get('aa_d'),t.uid('aa_b'),'other','Please clarify these terms') returning id as issue_id \gset
select t.put('aa_i',:'issue_id');
insert into meetany_private.company_reviews(request_id,author_id,company_id,rating,body,status) values(t.get('aa_r'),t.uid('aa_b'),t.uid('aa_s'),4,'A sufficiently long review','published') returning id as review_id \gset
select t.put('aa_review',:'review_id');
insert into meetany_private.conversations(client_id,company_id,request_id,context_key,started_by) values(t.uid('aa_b'),t.uid('aa_s'),t.get('aa_r'),t.get('aa_r')::text,t.uid('aa_b')) returning id as conversation_id \gset
select t.put('aa_conv',:'conversation_id');
